const config = {
  "previewFeatures": [],
  "clientVersion": "7.2.0",
  "engineVersion": "0c8ef2ce45c83248ab3df073180d5eda9e8be7a3",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================================\n// PRISMA SCHEMA - SCHOOL MANAGEMENT SYSTEM\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================================\n// BETTER AUTH — CORE MODELS\n// ============================================================================\n\nmodel User {\n  id            String   @id @default(cuid())\n  name          String\n  email         String   @unique\n  role          String   @default(\"user\") // e.g. \"superAdmin\" \n  emailVerified Boolean  @default(false)\n  image         String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Better Auth core relations\n  accounts Account[]\n  sessions Session[]\n\n  // Better Auth Organization Plugin relations\n  memberships Member[]\n  invitations Invitation[]\n\n  // Application relations (all named for clarity)\n  profile            UserProfile?\n  auditLogs          AuditLog[]\n  attendances        Attendance[]        @relation(\"AttendanceMarkedBy\")\n  gradingSystems     GradingSystem[]\n  componentScores    ComponentScore[]\n  transcriptRequests TranscriptRequest[]\n\n  // School & finance actor relations\n  schoolsCreated    School[]   @relation(\"SchoolCreator\")\n  billsIssued       Bill[]     @relation(\"BillIssuedBy\")\n  paymentsRecorded  Payment[]  @relation(\"PaymentRecordedBy\")\n  incomeRecorded    Income[]   @relation(\"IncomeRecordedBy\")\n  expensesApproved  Expense[]  @relation(\"ExpenseApprovedBy\")\n  expensesPaid      Expense[]  @relation(\"ExpensePaidBy\")\n  payrollsProcessed Payroll[]  @relation(\"PayrollProcessedBy\")\n  payrollsApproved  Payroll[]  @relation(\"PayrollApprovedBy\")\n  documentsUploaded Document[] @relation(\"DocumentUploadedBy\")\n\n  // Ledger\n  transactionsRecorded Transaction[] @relation(\"TransactionRecordedBy\")\n\n  // Assessment\n  customAssessmentTypesCreated CustomAssessmentType[] @relation(\"AssessmentTypeCreatedBy\")\n  teamMembers                  TeamMember[]\n\n  @@index([email])\n  @@map(\"users\")\n}\n\nmodel Session {\n  id        String   @id @default(cuid())\n  expiresAt DateTime\n  token     String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  ipAddress String?\n  userAgent String?\n  userId    String\n\n  // Better Auth Organization Plugin fields\n  impersonatedBy       String?\n  activeOrganizationId String?\n  activeTeamId         String? // Required when teams plugin is enabled\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([token])\n  @@index([activeOrganizationId])\n  @@index([activeTeamId])\n  @@map(\"sessions\")\n}\n\nmodel Account {\n  id                    String    @id @default(cuid())\n  accountId             String\n  providerId            String\n  userId                String\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([providerId, accountId])\n  @@index([userId])\n  @@map(\"accounts\")\n}\n\nmodel Verification {\n  id         String   @id @default(cuid())\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([identifier, value])\n  @@index([identifier])\n  @@index([expiresAt])\n  @@map(\"verifications\")\n}\n\n// ============================================================================\n// BETTER AUTH — ORGANIZATION PLUGIN MODELS\n// ============================================================================\n\nmodel Organization {\n  id        String   @id @default(cuid())\n  name      String\n  slug      String   @unique\n  logo      String?\n  metadata  Json? // Record<string, any> — stored as JSON per BA docs\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Plugin relations\n  members     Member[]\n  invitations Invitation[]\n  teams       Team[]\n  roles       OrganizationRole[]\n\n  // Application relation\n  school School?\n\n  @@index([slug])\n  @@map(\"organizations\")\n}\n\nmodel Member {\n  id             String   @id @default(cuid())\n  organizationId String\n  userId         String\n  role           String // Comma-separated: \"owner\", \"admin,member\", etc.\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user         User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, userId])\n  @@index([organizationId])\n  @@index([userId])\n  @@index([role])\n  @@map(\"members\")\n}\n\nmodel Invitation {\n  id             String   @id @default(cuid())\n  organizationId String\n  email          String\n  role           String\n  status         String   @default(\"pending\") // pending | accepted | rejected | cancelled\n  expiresAt      DateTime\n  createdAt      DateTime @default(now())\n  inviterId      String\n  teamId         String? // Required when teams plugin is enabled; null = no team assignment\n\n  inviter      User         @relation(fields: [inviterId], references: [id], onDelete: Cascade)\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  team         Team?        @relation(fields: [teamId], references: [id], onDelete: SetNull)\n\n  @@index([organizationId])\n  @@index([email])\n  @@index([status])\n  @@index([teamId])\n  @@map(\"invitations\")\n}\n\n// ---------------------------------------------------------------------------\n// Teams — sub-groups within an Organization\n// ---------------------------------------------------------------------------\n// Use-case: A school org might have teams like \"Teaching Staff\", \"Finance\",\n// \"Administration\".  Members can belong to one or more teams.  Invitations\n// can target a specific team.\n// ---------------------------------------------------------------------------\n\nmodel Team {\n  id             String   @id @default(cuid())\n  organizationId String\n  name           String\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  members      TeamMember[]\n  invitations  Invitation[]\n\n  @@unique([name, organizationId])\n  @@index([organizationId])\n  @@map(\"teams\")\n}\n\nmodel TeamMember {\n  id        String   @id @default(cuid())\n  teamId    String\n  userId    String\n  createdAt DateTime @default(now())\n\n  team Team @relation(fields: [teamId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([teamId, userId])\n  @@index([teamId])\n  @@index([userId])\n  @@map(\"team_members\")\n}\n\n// ---------------------------------------------------------------------------\n// OrganizationRole — Dynamic Access Control\n// ---------------------------------------------------------------------------\n\nmodel OrganizationRole {\n  id             String   @id @default(cuid())\n  organizationId String\n  role           String // Unique role name within the org\n  permission     Json // e.g. { \"student\": [\"create\",\"update\"], \"bill\": [\"create\"] }\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([role, organizationId])\n  @@index([organizationId])\n  @@map(\"organization_roles\")\n}\n\n// ============================================================================\n// SCHOOL & SUBSCRIPTION\n// ============================================================================\n\nmodel School {\n  id             String  @id @default(cuid())\n  organizationId String  @unique\n  name           String\n  code           String  @unique\n  email          String?\n  phone          String?\n  address        String?\n  logo           String?\n  motto          String?\n  website        String?\n  subdomain      String  @unique\n\n  // Localisation & theming\n  currency       String @default(\"GHS\")\n  timezone       String @default(\"Africa/Accra\")\n  locale         String @default(\"en-GH\")\n  primaryColor   String @default(\"#3B82F6\")\n  secondaryColor String @default(\"#10B981\")\n  settings       Json?\n  features       Json?\n\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  createdById String\n\n  // Relations\n  organization Organization  @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  createdBy    User          @relation(\"SchoolCreator\", fields: [createdById], references: [id])\n  subscription Subscription?\n\n  // Academic structure\n  academicYears AcademicYear[]\n  departments   Department[]\n  houses        House[]\n  classes       Class[]\n  subjects      Subject[]\n\n  // People\n  students  Student[]\n  teachers  Teacher[]\n  staff     Staff[]\n  guardians Guardian[]\n\n  // Finance\n  feeStructures FeeStructure[]\n  bills         Bill[]\n  payments      Payment[]\n  income        Income[]\n  expenses      Expense[]\n  payrolls      Payroll[]\n  chartAccounts ChartAccount[]\n  transactions  Transaction[]\n\n  // Assessment & documents\n  assessmentTemplates   AssessmentTemplate[]\n  gradingSystems        GradingSystem[]\n  customAssessmentTypes CustomAssessmentType[]\n  documents             Document[]\n\n  // Custom categories\n  customFeeCategories     CustomFeeCategory[]\n  customExpenseCategories CustomExpenseCategory[]\n  customIncomeCategories  CustomIncomeCategory[]\n\n  @@index([organizationId])\n  @@index([code])\n  @@index([subdomain])\n  @@index([createdById])\n  @@map(\"schools\")\n}\n\nmodel Subscription {\n  id           String             @id @default(cuid())\n  schoolId     String             @unique\n  planType     PlanType           @default(FREE)\n  planName     String             @default(\"Free Plan\")\n  billingCycle BillingCycle?\n  status       SubscriptionStatus @default(ACTIVE)\n  amount       Decimal?           @db.Decimal(10, 2)\n  currency     String             @default(\"USD\")\n\n  // Trial window\n  trialStartsAt DateTime?\n  trialEndsAt   DateTime?\n  isOnTrial     Boolean   @default(false)\n\n  // Current billing period\n  currentPeriodStart DateTime?\n  currentPeriodEnd   DateTime?\n\n  // Stripe integration\n  stripeCustomerId      String? @unique\n  stripeSubscriptionId  String? @unique\n  stripePaymentMethodId String?\n\n  // Cancellation\n  cancelAtPeriodEnd Boolean   @default(false)\n  canceledAt        DateTime?\n\n  // Soft limits per plan\n  maxStudents Int?\n  maxTeachers Int?\n  maxStaff    Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  school   School          @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  invoices InvoiceRecord[]\n\n  @@index([schoolId])\n  @@index([status])\n  @@index([planType])\n  @@index([stripeCustomerId])\n  @@index([stripeSubscriptionId])\n  @@map(\"subscriptions\")\n}\n\nmodel InvoiceRecord {\n  id              String        @id @default(cuid())\n  subscriptionId  String\n  invoiceNumber   String        @unique\n  amount          Decimal       @db.Decimal(10, 2)\n  currency        String        @default(\"USD\")\n  status          InvoiceStatus @default(PENDING)\n  periodStart     DateTime\n  periodEnd       DateTime\n  paidAt          DateTime?\n  paymentMethod   String?\n  stripeInvoiceId String?       @unique\n  invoiceUrl      String?\n  pdfUrl          String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  subscription Subscription @relation(fields: [subscriptionId], references: [id], onDelete: Cascade)\n\n  @@index([subscriptionId])\n  @@index([status])\n  @@map(\"invoice_records\")\n}\n\n// ============================================================================\n// USER PROFILES\n// ============================================================================\n\nmodel UserProfile {\n  id                    String    @id @default(cuid())\n  userId                String    @unique\n  firstName             String\n  lastName              String\n  otherNames            String?\n  phone                 String?\n  alternatePhone        String?\n  gender                Gender\n  dateOfBirth           DateTime  @db.Date\n  nationality           String    @default(\"Ghanaian\")\n  residentialAddress    String?\n  postalAddress         String?\n  city                  String?\n  region                String?\n  country               String    @default(\"Ghana\")\n  emergencyContactName  String?\n  emergencyContactPhone String?\n  emergencyRelationship String?\n  isActive              Boolean   @default(true)\n  lastLoginAt           DateTime?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  student  Student?\n  teacher  Teacher?\n  staff    Staff?\n  guardian Guardian?\n\n  @@index([userId])\n  @@index([isActive])\n  @@map(\"user_profiles\")\n}\n\n// ============================================================================\n// ACADEMIC STRUCTURE\n// ============================================================================\n\nmodel AcademicYear {\n  id        String   @id @default(cuid())\n  schoolId  String\n  name      String // e.g. \"2024/2025\"\n  startDate DateTime @db.Date\n  endDate   DateTime @db.Date\n  isCurrent Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  school      School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  terms       Term[]\n  classes     Class[]\n  enrollments Enrollment[]\n  bills       Bill[]\n\n  @@unique([name, schoolId])\n  @@index([schoolId, isCurrent])\n  @@index([startDate, endDate])\n  @@map(\"academic_years\")\n}\n\nmodel Term {\n  id             String   @id @default(cuid())\n  academicYearId String\n  name           String // e.g. \"First Term\"\n  termNumber     Int // 1 | 2 | 3\n  startDate      DateTime @db.Date\n  endDate        DateTime @db.Date\n  isCurrent      Boolean  @default(false)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  academicYear     AcademicYear      @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n  enrollments      Enrollment[]\n  bills            Bill[]\n  assessmentScores AssessmentScore[]\n  remarks          Remark[]\n  attendances      Attendance[]\n\n  @@unique([academicYearId, termNumber])\n  @@index([academicYearId])\n  @@index([isCurrent])\n  @@index([startDate, endDate])\n  @@map(\"terms\")\n}\n\nmodel Department {\n  id           String   @id @default(cuid())\n  schoolId     String\n  name         String\n  code         String\n  description  String?\n  headOfDeptId String?\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  school     School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  headOfDept Teacher?  @relation(\"DepartmentHead\", fields: [headOfDeptId], references: [id])\n  teachers   Teacher[] @relation(\"TeacherDepartment\")\n  subjects   Subject[]\n  students   Student[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@index([headOfDeptId])\n  @@map(\"departments\")\n}\n\n// ---------------------------------------------------------------------------\n// House system — core to Ghanaian school culture.\n// Every student MUST belong to a house; teachers optionally do too.\n// `points` tracks inter-house competition scores.\n// ---------------------------------------------------------------------------\n\nmodel House {\n  id             String   @id @default(cuid())\n  schoolId       String\n  name           String\n  code           String\n  description    String?\n  color          String?\n  motto          String?\n  houseTeacherId String?\n  points         Int      @default(0)\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  school       School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  houseTeacher Teacher?  @relation(\"HouseTeacher\", fields: [houseTeacherId], references: [id])\n  students     Student[]\n  teachers     Teacher[] @relation(\"TeacherHouse\")\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@index([houseTeacherId])\n  @@map(\"houses\")\n}\n\n// ---------------------------------------------------------------------------\n// Class\n// level   = the grade band:   \"Basic 7\", \"Form 1\", \"JHS 1\"\n// section = optional sub-group: \"A\", \"B\", \"C\"  (null for single-section)\n// name    = display name:      \"Basic 7A\", \"Form 1\"\n// ---------------------------------------------------------------------------\n\nmodel Class {\n  id             String   @id @default(cuid())\n  schoolId       String\n  academicYearId String\n  name           String\n  level          String\n  section        String?\n  capacity       Int?\n  classTeacherId String?\n  roomNumber     String?\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  school       School         @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear   @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n  classTeacher Teacher?       @relation(fields: [classTeacherId], references: [id])\n  students     Student[]\n  enrollments  Enrollment[]\n  subjects     ClassSubject[]\n  attendances  Attendance[]\n\n  @@unique([name, academicYearId, schoolId])\n  @@index([schoolId, isActive])\n  @@index([academicYearId])\n  @@index([level, schoolId])\n  @@index([classTeacherId])\n  @@map(\"classes\")\n}\n\nmodel Subject {\n  id           String   @id @default(cuid())\n  schoolId     String\n  departmentId String\n  name         String\n  code         String\n  description  String?\n  creditHours  Int      @default(1)\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  school           School            @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  department       Department        @relation(fields: [departmentId], references: [id])\n  classSubjects    ClassSubject[]\n  teachers         SubjectTeacher[]\n  assessmentScores AssessmentScore[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@index([departmentId])\n  @@map(\"subjects\")\n}\n\n// Many-to-many: which subjects are offered in which class\nmodel ClassSubject {\n  id           String   @id @default(cuid())\n  classId      String\n  subjectId    String\n  isCompulsory Boolean  @default(true)\n  createdAt    DateTime @default(now())\n\n  class   Class   @relation(fields: [classId], references: [id], onDelete: Cascade)\n  subject Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n\n  @@unique([classId, subjectId])\n  @@index([classId])\n  @@index([subjectId])\n  @@map(\"class_subjects\")\n}\n\n// Many-to-many: which teachers teach which subjects\nmodel SubjectTeacher {\n  id        String   @id @default(cuid())\n  subjectId String\n  teacherId String\n  createdAt DateTime @default(now())\n\n  subject Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  teacher Teacher @relation(fields: [teacherId], references: [id], onDelete: Cascade)\n\n  @@unique([subjectId, teacherId])\n  @@index([subjectId])\n  @@index([teacherId])\n  @@map(\"subject_teachers\")\n}\n\n// ============================================================================\n// PEOPLE\n// ============================================================================\n\nmodel Student {\n  id                 String        @id @default(cuid())\n  profileId          String        @unique\n  schoolId           String\n  studentId          String // School-scoped auto-generated ID, e.g. \"STU-2024-001\"\n  admissionNumber    String?\n  admissionDate      DateTime      @default(now()) @db.Date\n  classId            String?\n  departmentId       String?\n  houseId            String // REQUIRED — every student belongs to a house\n  previousSchool     String?\n  previousClass      String?\n  bloodGroup         String?\n  allergies          String?\n  medicalConditions  String?\n  outstandingBalance Decimal       @default(0) @db.Decimal(10, 2)\n  status             StudentStatus @default(ACTIVE)\n  graduationDate     DateTime?     @db.Date\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  profile          UserProfile         @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  school           School              @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  class            Class?              @relation(fields: [classId], references: [id])\n  department       Department?         @relation(fields: [departmentId], references: [id])\n  house            House               @relation(fields: [houseId], references: [id])\n  guardians        GuardianStudent[]\n  enrollments      Enrollment[]\n  attendances      Attendance[]\n  assessmentScores AssessmentScore[]\n  remarks          Remark[]\n  bills            Bill[]\n  payments         Payment[]\n  documents        Document[]\n  transcripts      TranscriptRequest[]\n\n  @@unique([studentId, schoolId])\n  @@unique([admissionNumber, schoolId])\n  @@index([schoolId, status])\n  @@index([classId, schoolId])\n  @@index([departmentId])\n  @@index([houseId])\n  @@index([profileId])\n  @@map(\"students\")\n}\n\nmodel Teacher {\n  id              String         @id @default(cuid())\n  profileId       String         @unique\n  schoolId        String\n  teacherId       String // School-scoped auto-generated ID\n  staffNumber     String?\n  departmentId    String\n  houseId         String? // Teachers optionally belong to a house\n  qualification   String?\n  specialization  String?\n  experience      Int? // Years of teaching experience\n  employmentType  EmploymentType @default(FULL_TIME)\n  hireDate        DateTime       @default(now()) @db.Date\n  contractEndDate DateTime?      @db.Date\n  monthlySalary   Decimal?       @db.Decimal(10, 2)\n  isActive        Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  profile               UserProfile      @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  school                School           @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  department            Department       @relation(\"TeacherDepartment\", fields: [departmentId], references: [id])\n  house                 House?           @relation(\"TeacherHouse\", fields: [houseId], references: [id])\n  departmentsAsHead     Department[]     @relation(\"DepartmentHead\")\n  housesAsHouseTeacher  House[]          @relation(\"HouseTeacher\")\n  classesAsClassTeacher Class[]\n  subjects              SubjectTeacher[]\n  remarks               Remark[]\n  documents             Document[]\n\n  @@unique([teacherId, schoolId])\n  @@unique([staffNumber, schoolId])\n  @@index([schoolId, isActive])\n  @@index([departmentId])\n  @@index([houseId])\n  @@index([profileId])\n  @@map(\"teachers\")\n}\n\nmodel Staff {\n  id              String         @id @default(cuid())\n  profileId       String         @unique\n  schoolId        String\n  staffId         String // School-scoped auto-generated ID\n  staffNumber     String?\n  staffType       StaffType\n  department      String? // Free-text department for non-teaching staff\n  jobTitle        String?\n  employmentType  EmploymentType @default(FULL_TIME)\n  hireDate        DateTime       @default(now()) @db.Date\n  contractEndDate DateTime?      @db.Date\n  monthlySalary   Decimal?       @db.Decimal(10, 2)\n  isActive        Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  profile   UserProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  school    School      @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  documents Document[]\n\n  @@unique([staffId, schoolId])\n  @@unique([staffNumber, schoolId])\n  @@index([schoolId, isActive])\n  @@index([staffType])\n  @@index([profileId])\n  @@map(\"staff\")\n}\n\nmodel Guardian {\n  id                 String       @id @default(cuid())\n  profileId          String?      @unique // null unless the guardian has a login account\n  schoolId           String\n  guardianId         String // School-scoped auto-generated ID\n  firstName          String\n  lastName           String\n  otherNames         String?\n  phone              String\n  alternatePhone     String?\n  email              String?\n  gender             Gender?\n  relationshipType   GuardianType\n  occupation         String?\n  employer           String?\n  workAddress        String?\n  workPhone          String?\n  residentialAddress String?\n  city               String?\n  region             String?\n  canLogin           Boolean      @default(false)\n  isActive           Boolean      @default(true)\n  createdAt          DateTime     @default(now())\n  updatedAt          DateTime     @updatedAt\n\n  school   School            @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  profile  UserProfile?      @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  students GuardianStudent[]\n\n  @@unique([guardianId, schoolId])\n  @@index([schoolId, isActive])\n  @@index([profileId])\n  @@index([email])\n  @@index([canLogin])\n  @@map(\"guardians\")\n}\n\n// Junction: guardian ↔ student with access-control flags\nmodel GuardianStudent {\n  id             String   @id @default(cuid())\n  guardianId     String\n  studentId      String\n  isPrimary      Boolean  @default(false) // Only one guardian should be primary\n  canPickup      Boolean  @default(true)\n  receiveReports Boolean  @default(true)\n  receiveAlerts  Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  guardian Guardian @relation(fields: [guardianId], references: [id], onDelete: Cascade)\n  student  Student  @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@unique([guardianId, studentId])\n  @@index([guardianId])\n  @@index([studentId])\n  @@index([isPrimary])\n  @@map(\"guardian_students\")\n}\n\n// ============================================================================\n// ENROLLMENT & ATTENDANCE\n// ============================================================================\n\nmodel Enrollment {\n  id             String           @id @default(cuid())\n  studentId      String\n  classId        String\n  academicYearId String\n  termId         String?\n  status         EnrollmentStatus @default(ACTIVE)\n  enrolledAt     DateTime         @default(now())\n  completedAt    DateTime?\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  student      Student      @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  class        Class        @relation(fields: [classId], references: [id], onDelete: Cascade)\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id], onDelete: Cascade)\n  term         Term?        @relation(fields: [termId], references: [id])\n\n  @@unique([studentId, classId, academicYearId, termId])\n  @@index([studentId])\n  @@index([classId, academicYearId, status])\n  @@index([academicYearId])\n  @@index([termId])\n  @@map(\"enrollments\")\n}\n\n// Attendance is scoped to a class and term for easy reporting\nmodel Attendance {\n  id         String           @id @default(cuid())\n  studentId  String\n  classId    String\n  termId     String\n  date       DateTime         @db.Date\n  status     AttendanceStatus\n  remarks    String?\n  markedById String\n  markedAt   DateTime         @default(now())\n  createdAt  DateTime         @default(now())\n  updatedAt  DateTime         @updatedAt\n\n  student  Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  class    Class   @relation(fields: [classId], references: [id], onDelete: Cascade)\n  term     Term    @relation(fields: [termId], references: [id], onDelete: Cascade)\n  markedBy User    @relation(\"AttendanceMarkedBy\", fields: [markedById], references: [id])\n\n  @@unique([studentId, date])\n  @@index([studentId])\n  @@index([classId, date])\n  @@index([termId])\n  @@index([date, status])\n  @@index([markedById])\n  @@map(\"attendances\")\n}\n\n// ============================================================================\n// ASSESSMENT & GRADING\n// ============================================================================\n\n// A grading system defines the scale (e.g. A/B/C/D/F with GPA points).\n// schoolId is nullable so system-default scales can be shared across schools.\nmodel GradingSystem {\n  id              String   @id @default(cuid())\n  schoolId        String?\n  name            String\n  code            String\n  description     String?\n  isSystemDefault Boolean  @default(false)\n  isSchoolDefault Boolean  @default(false)\n  isActive        Boolean  @default(true)\n  createdById     String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  school              School?              @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  createdBy           User?                @relation(fields: [createdById], references: [id])\n  gradeScales         GradeScale[]\n  assessmentTemplates AssessmentTemplate[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@index([createdById])\n  @@index([isSystemDefault])\n  @@index([isSchoolDefault])\n  @@map(\"grading_systems\")\n}\n\nmodel GradeScale {\n  id              String   @id @default(cuid())\n  gradingSystemId String\n  grade           String // e.g. \"A\", \"B+\", \"1\"\n  description     String // e.g. \"Excellent\"\n  minScore        Decimal  @db.Decimal(5, 2)\n  maxScore        Decimal  @db.Decimal(5, 2)\n  gradePoint      Decimal  @db.Decimal(3, 2) // GPA value\n  displayOrder    Int\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  gradingSystem GradingSystem @relation(fields: [gradingSystemId], references: [id], onDelete: Cascade)\n\n  @@unique([gradingSystemId, grade])\n  @@index([gradingSystemId])\n  @@index([minScore, maxScore])\n  @@map(\"grade_scales\")\n}\n\n// An assessment template defines the structure (components + weights) for a\n// particular subject/level/term combination.\nmodel AssessmentTemplate {\n  id              String   @id @default(cuid())\n  schoolId        String\n  gradingSystemId String\n  name            String\n  description     String?\n  classLevel      String? // e.g. \"Basic 7\"\n  subjectCode     String? // Links logically to Subject.code\n  termNumber      Int? // 1 | 2 | 3\n  isActive        Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  school           School                @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  gradingSystem    GradingSystem         @relation(fields: [gradingSystemId], references: [id])\n  components       AssessmentComponent[]\n  assessmentScores AssessmentScore[]\n\n  @@index([schoolId, isActive])\n  @@index([gradingSystemId])\n  @@index([classLevel, subjectCode])\n  @@map(\"assessment_templates\")\n}\n\n// A single component inside a template (e.g. \"Mid-Term Exam\", \"Project\").\n// componentType  = system-wide standard type (enum, optional)\n// customAssessmentTypeId = school-defined type (optional)\n// At least one of the two should be set.\nmodel AssessmentComponent {\n  id                     String          @id @default(cuid())\n  templateId             String\n  name                   String\n  componentType          AssessmentType? // Standard type (optional)\n  customAssessmentTypeId String? // School-specific custom type (optional)\n  maxMarks               Decimal         @db.Decimal(6, 2)\n  weight                 Decimal         @db.Decimal(5, 2) // Percentage weight (e.g. 30.00)\n  displayOrder           Int\n  isRequired             Boolean         @default(true)\n  createdAt              DateTime        @default(now())\n  updatedAt              DateTime        @updatedAt\n\n  template             AssessmentTemplate    @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  customAssessmentType CustomAssessmentType? @relation(fields: [customAssessmentTypeId], references: [id])\n  scores               ComponentScore[]\n\n  @@index([templateId])\n  @@index([componentType])\n  @@index([customAssessmentTypeId])\n  @@map(\"assessment_components\")\n}\n\n// One row per student per subject per term — the aggregate result.\nmodel AssessmentScore {\n  id         String   @id @default(cuid())\n  studentId  String\n  subjectId  String\n  termId     String\n  templateId String\n  totalScore Decimal  @db.Decimal(6, 2)\n  percentage Decimal  @db.Decimal(5, 2)\n  grade      String?\n  gradePoint Decimal? @db.Decimal(3, 2)\n  position   Int? // Rank within the class for this subject/term\n  remarks    String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  student         Student            @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  subject         Subject            @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  term            Term               @relation(fields: [termId], references: [id], onDelete: Cascade)\n  template        AssessmentTemplate @relation(fields: [templateId], references: [id])\n  componentScores ComponentScore[]\n\n  @@unique([studentId, subjectId, termId])\n  @@index([studentId, termId])\n  @@index([subjectId, termId])\n  @@index([templateId])\n  @@map(\"assessment_scores\")\n}\n\n// Per-component score that rolls up into AssessmentScore.\nmodel ComponentScore {\n  id                String   @id @default(cuid())\n  assessmentScoreId String\n  componentId       String\n  marksObtained     Decimal  @db.Decimal(6, 2)\n  maxMarks          Decimal  @db.Decimal(6, 2)\n  percentage        Decimal  @db.Decimal(5, 2)\n  weightedScore     Decimal  @db.Decimal(6, 2)\n  recordedById      String?\n  recordedAt        DateTime @default(now())\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  assessmentScore AssessmentScore     @relation(fields: [assessmentScoreId], references: [id], onDelete: Cascade)\n  component       AssessmentComponent @relation(fields: [componentId], references: [id])\n  recordedBy      User?               @relation(fields: [recordedById], references: [id])\n\n  @@unique([assessmentScoreId, componentId])\n  @@index([assessmentScoreId])\n  @@index([componentId])\n  @@index([recordedById])\n  @@map(\"component_scores\")\n}\n\nmodel Remark {\n  id         String     @id @default(cuid())\n  studentId  String\n  teacherId  String\n  termId     String\n  remarkType RemarkType\n  content    String\n  createdAt  DateTime   @default(now())\n  updatedAt  DateTime   @updatedAt\n\n  student Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  teacher Teacher @relation(fields: [teacherId], references: [id])\n  term    Term    @relation(fields: [termId], references: [id], onDelete: Cascade)\n\n  @@index([studentId, termId])\n  @@index([teacherId])\n  @@index([remarkType])\n  @@map(\"remarks\")\n}\n\nmodel TranscriptRequest {\n  id            String                @id @default(cuid())\n  studentId     String\n  requestType   TranscriptRequestType\n  purpose       String?\n  status        RequestStatus         @default(PENDING)\n  requestedAt   DateTime              @default(now())\n  processedAt   DateTime?\n  processedById String?\n  createdAt     DateTime              @default(now())\n  updatedAt     DateTime              @updatedAt\n\n  student     Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  processedBy User?   @relation(fields: [processedById], references: [id])\n\n  @@index([studentId])\n  @@index([status])\n  @@index([requestedAt])\n  @@index([processedById])\n  @@map(\"transcript_requests\")\n}\n\n// Schools can define their own assessment types beyond the standard enum\nmodel CustomAssessmentType {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  code        String\n  description String?\n  category    String? // \"Formative\", \"Summative\", \"Continuous Assessment\", etc.\n  isActive    Boolean  @default(true)\n  createdById String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school               School                @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  createdBy            User                  @relation(\"AssessmentTypeCreatedBy\", fields: [createdById], references: [id])\n  assessmentComponents AssessmentComponent[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@index([category])\n  @@index([createdById])\n  @@map(\"custom_assessment_types\")\n}\n\n// ============================================================================\n// FINANCE — TWO-LAYER ACCOUNTING\n// ============================================================================\n// BUSINESS LAYER  — what staff actually interact with day-to-day:\n//     Income      → non-fee revenue (donations, grants, rental …)\n//     Bill        → student fee invoices\n//     Payment     → student fee receipts\n//     Expense     → operational spend with an approval workflow\n//     Payroll     → monthly salary runs\n//\n// LEDGER LAYER    — the double-entry general ledger for auditors:\n//     ChartAccount  → the chart of accounts (hierarchical)\n//     Transaction   → every debit/credit pair that moves money\n//\n// Every business event that moves money automatically creates one or more\n// Transactions.  Transaction links back to its source via typed nullable FKs\n// (sourcePaymentId, sourceIncomeId, sourceExpenseId, sourceSalaryId,\n// sourcePayrollId).  Only one of those will be non-null per row; MANUAL\n// entries leave them all null.  This gives referential integrity instead of\n// fragile free-text polymorphic fields.\n//\n// Typical flows:\n//   Student pays fee   → Payment created → Transaction: DR Bank, CR A/R\n//   Donation received  → Income created  → Transaction: DR Bank, CR Donations\n//   Expense approved & paid → Expense  → Transaction: DR Expense acct, CR Bank\n//   Payroll paid       → Payroll/Salary → Transaction per salary line:\n//                                           DR Salaries, CR Bank\n// ============================================================================\n\n// ---------------------------------------------------------------------------\n// Non-fee income (donations, grants, fundraising, rental, etc.)\n// ---------------------------------------------------------------------------\n\nmodel Income {\n  id               String         @id @default(cuid())\n  schoolId         String\n  incomeNumber     String // Auto-generated: \"INC-2024-001\"\n  date             DateTime       @db.Date\n  description      String\n  amount           Decimal        @db.Decimal(10, 2)\n  category         IncomeCategory\n  customCategoryId String?\n  source           String? // Who paid / source description\n  paymentMethod    PaymentMethod\n  referenceNumber  String? // Bank / mobile-money reference\n  receiptNumber    String?\n  receiptUrl       String?\n  recordedById     String\n  notes            String?\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  school         School                @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  customCategory CustomIncomeCategory? @relation(fields: [customCategoryId], references: [id])\n  recordedBy     User                  @relation(\"IncomeRecordedBy\", fields: [recordedById], references: [id])\n  transaction    Transaction? // Ledger entry created when income is recorded\n\n  @@index([schoolId, date])\n  @@index([category])\n  @@index([customCategoryId])\n  @@index([recordedById])\n  @@map(\"income\")\n}\n\n// ---------------------------------------------------------------------------\n// Fee structures & billing\n// ---------------------------------------------------------------------------\n\nmodel FeeStructure {\n  id           String   @id @default(cuid())\n  schoolId     String\n  name         String // e.g. \"Form 1 Fees — First Term 2024/2025\"\n  description  String?\n  academicYear String? // e.g. \"2024/2025\"  (free-text, not FK — structures outlive years)\n  classLevel   String? // e.g. \"Form 1\"\n  termNumber   Int? // 1 | 2 | 3\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  school School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  items  FeeItem[]\n  bills  Bill[]\n\n  @@index([schoolId, isActive])\n  @@index([academicYear, classLevel])\n  @@map(\"fee_structures\")\n}\n\nmodel FeeItem {\n  id               String       @id @default(cuid())\n  feeStructureId   String\n  name             String\n  description      String?\n  amount           Decimal      @db.Decimal(10, 2)\n  category         FeeCategory?\n  customCategoryId String?\n  isOptional       Boolean      @default(false)\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  feeStructure   FeeStructure       @relation(fields: [feeStructureId], references: [id], onDelete: Cascade)\n  customCategory CustomFeeCategory? @relation(fields: [customCategoryId], references: [id])\n  billItems      BillItem[]\n\n  @@index([feeStructureId])\n  @@index([category])\n  @@index([customCategoryId])\n  @@map(\"fee_items\")\n}\n\nmodel Bill {\n  id             String     @id @default(cuid())\n  schoolId       String\n  studentId      String\n  academicYearId String\n  termId         String?\n  feeStructureId String?\n  billNumber     String // Auto-generated: \"BILL-2024-001\"\n  totalAmount    Decimal    @db.Decimal(10, 2)\n  paidAmount     Decimal    @default(0) @db.Decimal(10, 2)\n  balanceAmount  Decimal    @db.Decimal(10, 2)\n  discount       Decimal?   @default(0) @db.Decimal(10, 2) // Scholarship / waiver discount\n  status         BillStatus @default(PENDING)\n  dueDate        DateTime?  @db.Date\n  issuedAt       DateTime   @default(now())\n  issuedById     String?\n  notes          String?\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  student      Student       @relation(fields: [studentId], references: [id])\n  academicYear AcademicYear  @relation(fields: [academicYearId], references: [id])\n  term         Term?         @relation(fields: [termId], references: [id])\n  feeStructure FeeStructure? @relation(fields: [feeStructureId], references: [id])\n  issuedBy     User?         @relation(\"BillIssuedBy\", fields: [issuedById], references: [id])\n  items        BillItem[]\n  payments     Payment[]\n\n  @@unique([billNumber, schoolId])\n  @@index([schoolId, status])\n  @@index([studentId, academicYearId])\n  @@index([dueDate])\n  @@index([issuedById])\n  @@map(\"bills\")\n}\n\nmodel BillItem {\n  id          String   @id @default(cuid())\n  billId      String\n  feeItemId   String? // null when the line-item was manually added\n  description String\n  amount      Decimal  @db.Decimal(10, 2) // Unit price\n  quantity    Int      @default(1)\n  totalAmount Decimal  @db.Decimal(10, 2) // amount × quantity\n  createdAt   DateTime @default(now())\n\n  bill    Bill     @relation(fields: [billId], references: [id], onDelete: Cascade)\n  feeItem FeeItem? @relation(fields: [feeItemId], references: [id])\n\n  @@index([billId])\n  @@index([feeItemId])\n  @@map(\"bill_items\")\n}\n\n// Student fee payment — rich detail for the payment methods common in Ghana\nmodel Payment {\n  id              String        @id @default(cuid())\n  schoolId        String\n  studentId       String\n  billId          String? // null for advance / partial payments not yet linked\n  paymentNumber   String // Auto-generated: \"PAY-2024-001\"\n  amount          Decimal       @db.Decimal(10, 2)\n  paymentMethod   PaymentMethod\n  paymentDate     DateTime      @db.Date\n  referenceNumber String? // Bank ref / mobile-money transaction ID\n  bankName        String?\n  accountNumber   String?\n  chequeNumber    String?\n  chequeDate      DateTime?     @db.Date\n  status          PaymentStatus @default(COMPLETED)\n  notes           String?\n  recordedById    String\n  receiptUrl      String? // Generated receipt PDF\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  school      School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  student     Student      @relation(fields: [studentId], references: [id])\n  bill        Bill?        @relation(fields: [billId], references: [id])\n  recordedBy  User         @relation(\"PaymentRecordedBy\", fields: [recordedById], references: [id])\n  transaction Transaction? // Ledger entry created when payment is recorded\n\n  @@index([schoolId, paymentDate])\n  @@index([studentId])\n  @@index([billId])\n  @@index([paymentNumber])\n  @@index([paymentMethod])\n  @@index([status])\n  @@index([recordedById])\n  @@map(\"payments\")\n}\n\n// ---------------------------------------------------------------------------\n// Expense management — with approval workflow\n// ---------------------------------------------------------------------------\n// Flow: PENDING → APPROVED → PAID  (or REJECTED / CANCELLED at any point)\n// ---------------------------------------------------------------------------\n\nmodel Expense {\n  id               String           @id @default(cuid())\n  schoolId         String\n  expenseNumber    String // Auto-generated: \"EXP-2024-001\"\n  date             DateTime         @db.Date\n  description      String\n  amount           Decimal          @db.Decimal(10, 2)\n  category         ExpenseCategory?\n  customCategoryId String?\n  paymentMethod    PaymentMethod\n  paidTo           String? // Vendor / payee name\n  referenceNumber  String? // Cheque number, bank reference, etc.\n  receiptNumber    String?\n  receiptUrl       String?\n  status           ExpenseStatus    @default(PENDING)\n  requestedBy      String? // Name / description of who requested\n  approvedById     String?\n  approvedAt       DateTime?\n  paidById         String?\n  paidAt           DateTime?\n  notes            String?\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n\n  school         School                 @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  approvedBy     User?                  @relation(\"ExpenseApprovedBy\", fields: [approvedById], references: [id])\n  paidBy         User?                  @relation(\"ExpensePaidBy\", fields: [paidById], references: [id])\n  customCategory CustomExpenseCategory? @relation(fields: [customCategoryId], references: [id])\n  transaction    Transaction? // Ledger entry created when expense is paid\n\n  @@unique([expenseNumber, schoolId])\n  @@index([schoolId, date])\n  @@index([schoolId, status]) // Dashboard: expenses by school + status\n  @@index([category])\n  @@index([customCategoryId])\n  @@index([status])\n  @@index([approvedById])\n  @@index([paidById])\n  @@map(\"expenses\")\n}\n\n// ---------------------------------------------------------------------------\n// Payroll — monthly salary processing for teachers & staff\n// ---------------------------------------------------------------------------\n// Flow: DRAFT → PENDING_APPROVAL → APPROVED → PAID  (or CANCELLED)\n// ---------------------------------------------------------------------------\n\nmodel Payroll {\n  id              String        @id @default(cuid())\n  schoolId        String\n  payrollNumber   String // Auto-generated: \"PAYROLL-2024-JAN\"\n  month           Int // 1–12\n  year            Int // e.g. 2024\n  payPeriodStart  DateTime      @db.Date\n  payPeriodEnd    DateTime      @db.Date\n  totalGrossPay   Decimal       @db.Decimal(12, 2)\n  totalDeductions Decimal       @default(0) @db.Decimal(12, 2)\n  totalNetPay     Decimal       @db.Decimal(12, 2)\n  status          PayrollStatus @default(DRAFT)\n  processedById   String?\n  processedAt     DateTime?\n  approvedById    String?\n  approvedAt      DateTime?\n  paidAt          DateTime?\n  notes           String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  school       School        @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  processedBy  User?         @relation(\"PayrollProcessedBy\", fields: [processedById], references: [id])\n  approvedBy   User?         @relation(\"PayrollApprovedBy\", fields: [approvedById], references: [id])\n  salaries     Salary[]\n  transactions Transaction[] // Ledger entries created when payroll is paid (one per salary line)\n\n  @@unique([schoolId, month, year])\n  @@index([schoolId, status])\n  @@index([year, month])\n  @@index([processedById])\n  @@index([approvedById])\n  @@map(\"payrolls\")\n}\n\n// Individual salary line within a payroll run.\n// employeeType + employeeId together identify the Teacher or Staff record.\n// employeeName / employeeNumber are denormalised for PDF generation speed.\nmodel Salary {\n  id             String       @id @default(cuid())\n  payrollId      String\n  employeeType   EmployeeType // TEACHER | STAFF\n  employeeId     String // Teacher.id or Staff.id (no FK — polymorphic)\n  employeeName   String // Cached full name\n  employeeNumber String? // Cached staff/teacher number\n  baseSalary     Decimal      @db.Decimal(10, 2)\n  allowances     Decimal      @default(0) @db.Decimal(10, 2)\n  bonuses        Decimal      @default(0) @db.Decimal(10, 2)\n  grossPay       Decimal      @db.Decimal(10, 2)\n\n  // Deductions\n  tax             Decimal @default(0) @db.Decimal(10, 2) // Income tax\n  ssnit           Decimal @default(0) @db.Decimal(10, 2) // Ghana Social Security (SSNIT)\n  loans           Decimal @default(0) @db.Decimal(10, 2) // Staff loan repayments\n  otherDeductions Decimal @default(0) @db.Decimal(10, 2)\n  totalDeductions Decimal @db.Decimal(10, 2)\n\n  netPay           Decimal        @db.Decimal(10, 2)\n  paymentMethod    PaymentMethod?\n  paymentDate      DateTime?      @db.Date\n  paymentReference String?\n  notes            String?\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  payroll     Payroll      @relation(fields: [payrollId], references: [id], onDelete: Cascade)\n  transaction Transaction? // Ledger entry created when salary is paid\n\n  @@index([employeeType, employeeId])\n  @@map(\"salaries\")\n}\n\n// ============================================================================\n// LEDGER LAYER — DOUBLE-ENTRY GENERAL LEDGER\n// ============================================================================\n\n// ---------------------------------------------------------------------------\n// Chart of Accounts — hierarchical account tree.\n// Every school sets up its own chart.  Accounts nest via parentId so you can\n// build trial balances, balance sheets, and P&Ls at any level of detail.\n// `balance` is a denormalised running total maintained by the application\n// whenever a Transaction touches this account — avoids a SUM on every read.\n// ---------------------------------------------------------------------------\n\nmodel ChartAccount {\n  id          String          @id @default(cuid())\n  schoolId    String\n  code        String // e.g. \"1000\", \"1001\", \"4100\"\n  name        String // e.g. \"Cash and Bank\", \"School Fee Revenue\"\n  description String?\n  accountType AccountType // ASSET | LIABILITY | EQUITY | REVENUE | EXPENSE\n  category    AccountCategory // Fine-grained bucket within the type\n  parentId    String? // Self-referential: null = top-level account\n  balance     Decimal         @default(0) @db.Decimal(15, 2) // Denormalised running balance\n  isActive    Boolean         @default(true)\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  school             School         @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  parent             ChartAccount?  @relation(\"AccountHierarchy\", fields: [parentId], references: [id])\n  children           ChartAccount[] @relation(\"AccountHierarchy\")\n  debitTransactions  Transaction[]  @relation(\"DebitAccount\")\n  creditTransactions Transaction[]  @relation(\"CreditAccount\")\n\n  @@unique([code, schoolId])\n  @@index([schoolId, accountType])\n  @@index([schoolId, isActive])\n  @@index([category])\n  @@index([parentId])\n  @@map(\"chart_accounts\")\n}\n\n// ---------------------------------------------------------------------------\n// Transaction — one row per debit/credit pair.\n//\n// Source traceability:\n//   sourceType tells you what kind of business event created this entry.\n//   Exactly one of the source*Id FKs will be non-null (or all null for MANUAL).\n//   This gives full referential integrity and lets you join directly back to\n//   the originating Payment / Income / Expense / Salary / Payroll without\n//   any string-based polymorphism.\n//\n// Amount sign convention:\n//   `amount` is always positive.  The semantics come from which account is\n//   debited vs credited — standard double-entry.\n// ---------------------------------------------------------------------------\n\nmodel Transaction {\n  id                String   @id @default(cuid())\n  schoolId          String\n  transactionNumber String // Auto-generated: \"TXN-2024-001\"\n  transactionDate   DateTime @db.Date\n  description       String\n  amount            Decimal  @db.Decimal(15, 2) // Always positive\n  debitAccountId    String // ChartAccount that is debited\n  creditAccountId   String // ChartAccount that is credited\n\n  // Source traceability — typed nullable FKs (exactly one is set, or none for MANUAL)\n  sourceType      TransactionSourceType\n  sourcePaymentId String?               @unique // 1:1 — one Payment produces exactly one Transaction\n  sourceIncomeId  String?               @unique // 1:1\n  sourceExpenseId String?               @unique // 1:1\n  sourceSalaryId  String?               @unique // 1:1\n  sourcePayrollId String? // 1:N — a Payroll can have multiple Transactions (one per salary line)\n\n  recordedById String\n  notes        String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  school        School       @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  debitAccount  ChartAccount @relation(\"DebitAccount\", fields: [debitAccountId], references: [id])\n  creditAccount ChartAccount @relation(\"CreditAccount\", fields: [creditAccountId], references: [id])\n  recordedBy    User         @relation(\"TransactionRecordedBy\", fields: [recordedById], references: [id])\n\n  // Source relations — back-links to the business event that created this entry\n  sourcePayment Payment? @relation(fields: [sourcePaymentId], references: [id])\n  sourceIncome  Income?  @relation(fields: [sourceIncomeId], references: [id])\n  sourceExpense Expense? @relation(fields: [sourceExpenseId], references: [id])\n  sourceSalary  Salary?  @relation(fields: [sourceSalaryId], references: [id])\n  sourcePayroll Payroll? @relation(fields: [sourcePayrollId], references: [id])\n\n  @@unique([transactionNumber, schoolId])\n  @@index([schoolId, transactionDate]) // Primary ledger scan: school + date range\n  @@index([transactionNumber]) // Lookup by TXN number\n  @@index([debitAccountId, transactionDate]) // Account statement: debit side + date range\n  @@index([creditAccountId, transactionDate]) // Account statement: credit side + date range\n  @@index([sourcePayrollId]) // Only 1:N source relation — kept for \"txns for this payroll\"\n  @@index([recordedById]) // Audit: \"what did this user post?\"\n  @@map(\"transactions\")\n}\n\n// ============================================================================\n// CUSTOM CATEGORIES\n// ============================================================================\n\nmodel CustomFeeCategory {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  code        String\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school   School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  feeItems FeeItem[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@map(\"custom_fee_categories\")\n}\n\nmodel CustomExpenseCategory {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  code        String\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school   School    @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  expenses Expense[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@map(\"custom_expense_categories\")\n}\n\nmodel CustomIncomeCategory {\n  id          String   @id @default(cuid())\n  schoolId    String\n  name        String\n  code        String\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  school School   @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  income Income[]\n\n  @@unique([code, schoolId])\n  @@index([schoolId, isActive])\n  @@map(\"custom_income_categories\")\n}\n\n// ============================================================================\n// DOCUMENTS & AUDIT\n// ============================================================================\n\nmodel Document {\n  id           String             @id @default(cuid())\n  schoolId     String\n  title        String\n  description  String?\n  fileUrl      String\n  fileType     String\n  fileSize     Int // bytes\n  entityType   DocumentEntityType\n  entityId     String // Generic ID of the parent entity\n  studentId    String? // Convenience FK for direct queries\n  teacherId    String?\n  staffId      String?\n  uploadedById String\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n\n  school     School   @relation(fields: [schoolId], references: [id], onDelete: Cascade)\n  student    Student? @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  teacher    Teacher? @relation(fields: [teacherId], references: [id], onDelete: Cascade)\n  staff      Staff?   @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  uploadedBy User     @relation(\"DocumentUploadedBy\", fields: [uploadedById], references: [id])\n\n  @@index([schoolId])\n  @@index([entityType, entityId])\n  @@index([studentId])\n  @@index([teacherId])\n  @@index([staffId])\n  @@index([uploadedById])\n  @@map(\"documents\")\n}\n\nmodel AuditLog {\n  id         String      @id @default(cuid())\n  userId     String\n  action     AuditAction\n  entityType String\n  entityId   String\n  oldValues  Json?\n  newValues  Json?\n  ipAddress  String?\n  userAgent  String?\n  createdAt  DateTime    @default(now())\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entityType, entityId])\n  @@index([action])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ============================================================================\n// ENUMS\n// ============================================================================\n\n// --- Identity & People ---\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum GuardianType {\n  FATHER\n  MOTHER\n  GUARDIAN\n  SIBLING\n  RELATIVE\n  OTHER\n}\n\nenum StaffType {\n  ACCOUNTANT\n  ADMIN\n  LIBRARIAN\n  DRIVER\n  SECURITY\n  NURSE\n  COUNSELOR\n  IT_SUPPORT\n  RECEPTIONIST\n  COOK\n  CLEANER\n  OTHER\n}\n\nenum EmploymentType {\n  FULL_TIME\n  PART_TIME\n  CONTRACT\n  TEMPORARY\n  INTERN\n}\n\n// --- Academic ---\n\nenum StudentStatus {\n  ACTIVE\n  GRADUATED\n  WITHDRAWN\n  SUSPENDED\n  TRANSFERRED\n  EXPELLED\n  DECEASED\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  EXCUSED\n  SICK\n  PERMISSION\n}\n\nenum EnrollmentStatus {\n  ACTIVE\n  COMPLETED\n  WITHDRAWN\n  TRANSFERRED\n  SUSPENDED\n}\n\nenum AssessmentType {\n  FINAL_EXAM\n  MID_TERM_EXAM\n  CLASS_TEST\n  QUIZ\n  ASSIGNMENT\n  PROJECT\n  PRACTICAL\n  HOMEWORK\n  PRESENTATION\n  MOCK_EXAM\n}\n\nenum RemarkType {\n  ACADEMIC\n  BEHAVIORAL\n  ATTENDANCE\n  GENERAL\n  ACHIEVEMENT\n  CONCERN\n}\n\nenum RequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSING\n  COMPLETED\n  CANCELLED\n}\n\nenum TranscriptRequestType {\n  OFFICIAL\n  UNOFFICIAL\n  BECE_TRANSCRIPT\n  WASSCE_TRANSCRIPT\n  TRANSFER_CERTIFICATE\n  PROGRESS_REPORT\n  FINAL_TRANSCRIPT\n  OTHER\n}\n\n// --- Finance ---\n\nenum IncomeCategory {\n  SCHOOL_FEES // Revenue from student fee payments\n  DONATIONS\n  GRANTS // Government / NGO grants\n  FUNDRAISING // Events, sales\n  RENTAL // Building / equipment rental income\n  INVESTMENTS // Interest, dividends\n  MISCELLANEOUS\n}\n\nenum FeeCategory {\n  TUITION\n  ADMISSION\n  REGISTRATION\n  EXAM\n  LIBRARY\n  LABORATORY\n  SPORTS\n  TRANSPORT\n  MEAL\n  UNIFORM\n  BOOKS\n  TECHNOLOGY\n  HOSTEL\n  DEVELOPMENT\n  PTA\n  EXTRA_CLASSES\n  OTHER\n}\n\nenum BillStatus {\n  PENDING\n  PARTIALLY_PAID\n  PAID\n  OVERDUE\n  WAIVED\n  CANCELLED\n}\n\nenum PaymentMethod {\n  CASH\n  BANK_TRANSFER\n  CHEQUE\n  MOBILE_MONEY // MTN, Vodafone, AirtelTigo\n  CARD\n  ONLINE\n}\n\nenum PaymentStatus {\n  COMPLETED\n  PENDING\n  FAILED\n  REFUNDED\n  CANCELLED\n  BOUNCED // Cheque bounced\n}\n\nenum ExpenseCategory {\n  SALARIES\n  UTILITIES // Water, electricity, internet\n  SUPPLIES // Stationery, teaching materials\n  MAINTENANCE\n  TRANSPORT\n  RENT\n  FOOD // School feeding programme\n  CLEANING\n  SECURITY\n  COMMUNICATION // Phone, internet bills\n  PROFESSIONAL_FEES // Legal, accounting, consultancy\n  EQUIPMENT // Furniture, computers\n  TRAINING // Staff development\n  INSURANCE\n  TAXES\n  MISCELLANEOUS\n}\n\nenum ExpenseStatus {\n  PENDING\n  APPROVED\n  PAID\n  REJECTED\n  CANCELLED\n}\n\nenum PayrollStatus {\n  DRAFT\n  PENDING_APPROVAL\n  APPROVED\n  PAID\n  CANCELLED\n}\n\nenum EmployeeType {\n  TEACHER\n  STAFF\n}\n\n// --- Ledger ---\n\nenum AccountType {\n  ASSET\n  LIABILITY\n  EQUITY\n  REVENUE\n  EXPENSE\n}\n\nenum AccountCategory {\n  // Assets\n  CASH\n  BANK\n  ACCOUNTS_RECEIVABLE\n  FIXED_ASSETS\n  INVENTORY\n  PREPAID_EXPENSES\n  // Liabilities\n  ACCOUNTS_PAYABLE\n  ACCRUED_EXPENSES\n  LONG_TERM_DEBT\n  // Equity\n  EQUITY_CAPITAL\n  RETAINED_EARNINGS\n  // Revenue\n  SCHOOL_FEES\n  OTHER_INCOME\n  // Expenses\n  SALARY_WAGES\n  UTILITIES\n  RENT\n  SUPPLIES\n  MAINTENANCE\n  TRANSPORT\n  INSURANCE\n  TAXES\n  OTHER_EXPENSE\n}\n\nenum TransactionSourceType {\n  PAYMENT // Originated from a student fee Payment\n  INCOME // Originated from an Income record\n  EXPENSE // Originated from an Expense record\n  SALARY // Originated from a Salary line inside a Payroll\n  PAYROLL // Aggregate payroll-level entry (if used instead of per-salary)\n  MANUAL // Hand-entered by accountant / admin (no source FK)\n}\n\n// --- Documents & Audit ---\n\nenum DocumentEntityType {\n  STUDENT\n  TEACHER\n  STAFF\n  SCHOOL\n  BILL\n  PAYMENT\n  EXPENSE\n  OTHER\n}\n\nenum AuditAction {\n  CREATE\n  UPDATE\n  DELETE\n  LOGIN\n  LOGOUT\n  PAYMENT_RECORDED\n  BILL_GENERATED\n  GRADE_ENTERED\n  ATTENDANCE_MARKED\n  EXPENSE_APPROVED\n  EXPENSE_PAID\n  PAYROLL_PROCESSED\n  INCOME_RECORDED\n}\n\n// --- SaaS / Subscription ---\n\nenum PlanType {\n  FREE\n  PREMIUM\n  ENTERPRISE\n  CUSTOM\n}\n\nenum BillingCycle {\n  MONTHLY\n  QUARTERLY\n  YEARLY\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  TRIALING\n  PAST_DUE\n  CANCELED\n  INCOMPLETE\n  INCOMPLETE_EXPIRED\n  UNPAID\n}\n\nenum InvoiceStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n  VOID\n}\n"
}

